<tbody>
<tr align="center">
<td><img decoding="async" src="https://www.pianoorgandepot.com/JPG/Baldwin-Cracked-Frame/Free-Piano-2.jpg" width="300" height="200" border="0"></td>
<td><img decoding="async" loading="lazy" src="https://www.pianoorgandepot.com/JPG/Baldwin-Cracked-Frame/Baldwin-Action-Out.jpg" width="300" height="200" border="0"></td>
